`timescale 1ns / 1ps
// tb_ips_gpio_irq_bank : production-line testbench for the GPIO IRQ bank core.
//
// Clocking: clk_en is generated by a free-running 12-state divisor in the
// testbench (it steps on every rising edge, so its value is settled long before
// any sampling point).  Exactly one enabled beat is produced per loop iteration,
// which is the step the Python golden model replays.
//
// Stimulus contract shared with models/ips_gpio_irq_bank.py, one LCG step per
// enabled beat:
//     state     = state * 1664525 + 1013904223  (mod 2**32), starting from SEED
//     pin_in    = {16'hBEEF, state[15:0]}
//     bus_addr  = state[3:0]
//     bus_we    = state[20]
//     bus_wdata = {16'hA5A5, ~state[15:0]}
//     bus_ack   = (state[13:10] == 4'hA)
// Only DUT outputs are folded into the digest (docs/IP_CORE_SOP.md trap T1: the
// expectation lives in the model, never here), and every check uses === so an X
// can never read as a pass (trap T6).  The run ends on a fixed edge count.
module tb_ips_gpio_irq_bank;

`include "ips_tb_common.vh"

localparam integer BEATS = 320;
localparam [31:0]  SEED  = 32'h5A170C0D;
localparam [3:0]   DIV   = 4'd11;

reg [3:0]  div_q;
wire       tick;
reg        rst_n;
reg [31:0] pin_in;
reg [3:0]  bus_addr;
reg        bus_we;
reg [31:0] bus_wdata;
reg        bus_ack;
reg [31:0] state;

wire [31:0] bus_rdata;
wire [15:0] pend;
wire [31:0] pin_out;
wire        irq_active;
wire [3:0]  irq_vec;
wire        storm;
wire        acked;
wire [1:0]  sync_idx;
wire [4:0]  set_evts;
wire [3:0]  w1c_evts;
wire [3:0]  err_count;
wire        level_any;

assign tick = (div_q == 4'd0);

always @(posedge ips_clk) begin
    div_q <= (div_q == DIV) ? 4'd0 : (div_q + 4'd1);
end

ips_gpio_irq_bank dut (
    .clk        (ips_clk),
    .clk_en     (tick),
    .rst_n      (rst_n),
    .pin_in     (pin_in),
    .bus_addr   (bus_addr),
    .bus_we     (bus_we),
    .bus_wdata  (bus_wdata),
    .bus_ack    (bus_ack),
    .bus_rdata  (bus_rdata),
    .pend       (pend),
    .pin_out    (pin_out),
    .irq_active (irq_active),
    .irq_vec    (irq_vec),
    .storm      (storm),
    .acked      (acked),
    .sync_idx   (sync_idx),
    .set_evts   (set_evts),
    .w1c_evts   (w1c_evts),
    .err_count  (err_count),
    .level_any  (level_any)
);

// One count per enabled rising edge, as the shared header contract requires.
always @(posedge ips_clk) begin
    if (tick === 1'b1) begin
        ips_cycle = ips_cycle + 32'd1;
    end
end

integer i;
reg     bad;

// Land on the negedge that opens an enabled beat window.
task beat;
begin
    @(negedge ips_clk);
    while (tick !== 1'b1) begin
        @(negedge ips_clk);
    end
end
endtask

initial begin
    ips_fnv_reset();
    rst_n     = 1'b0;
    div_q     = 4'd0;
    pin_in    = 32'h00000000;
    bus_addr  = 4'h0;
    bus_we    = 1'b0;
    bus_wdata = 32'h00000000;
    bus_ack   = 1'b0;
    state     = SEED;
    bad       = 1'b0;

    repeat (4) @(negedge ips_clk);
    // Release reset in the closed window right after an enabled edge that the
    // core still spent in reset, so the first enabled beat of the loop is also
    // the first beat the model replays.
    beat;
    @(negedge ips_clk);
    rst_n = 1'b1;

    for (i = 0; i < BEATS; i = i + 1) begin
        beat;
        state     = state * 32'd1664525 + 32'd1013904223;
        pin_in    = {16'hBEEF, state[15:0]};
        bus_addr  = state[3:0];
        bus_we    = state[20];
        bus_wdata = {16'hA5A5, ~state[15:0]};
        bus_ack   = (state[13:10] == 4'hA);

        @(negedge ips_clk);

        if ((^bus_rdata === 1'bx) || (^pend === 1'bx) || (^pin_out === 1'bx) ||
            (^irq_vec === 1'bx) || (^set_evts === 1'bx) || (^err_count === 1'bx)) begin
            bad = 1'b1;
        end
        if (storm === 1'b1 && set_evts !== 5'd28) begin
            bad = 1'b1;
        end
        if (irq_active === 1'b1 && pend === 16'h0000) begin
            bad = 1'b1;
        end
        if (level_any === 1'b1 && pend === 16'h0000) begin
            bad = 1'b1;
        end
        if (err_count === 4'hF || w1c_evts === 4'hF) begin
            bad = 1'b1;
        end

        ips_fnv_word(bus_rdata);
        ips_fnv_word({16'd0, pend});
        ips_fnv_word(pin_out);
        ips_fnv_word({26'd0, sync_idx, irq_active, level_any, storm, acked});
        ips_fnv_word({24'd0, irq_vec, err_count});
        ips_fnv_word({23'd0, set_evts, w1c_evts});
    end

    // Short drain: still inside the closed window, so no extra enabled beat
    // happens and the model's final state is exactly what is folded here.
    repeat (2) @(negedge ips_clk);
    ips_fnv_word({16'd0, pend});
    ips_fnv_word({28'd0, err_count});
    ips_fnv_word({27'd0, set_evts});
    ips_fnv_word(BEATS);

    ips_verdict(!bad, "ips_gpio_irq_bank");
end

endmodule
